(() => {
  const labels = {
    ultima: 'Acute on the ultima',
    antepenult: 'Acute on the antepenult',
    'penult-circumflex': 'Circumflex on the penult',
    barytone: 'Barytone only: position unspecified'
  };
  const rows = [];
  function group(words, pattern, rule, detail) {
    words.forEach(word => rows.push({word, pattern, rule, detail}));
  }
  group(['ἄφραστος','ἀλίαστος','ἄλαστος'], 'antepenult',
    'Compound examples in -στος.',
    'The passage assigns these compounds an antepenult acute. It contrasts φραστός with ἄφραστος.');
  group(['τάχιστος','ἄριστος','κάλλιστος','ἕκαστος'], 'antepenult',
    'The superlative examples, with ἕκαστος grouped alongside them.',
    'The passage assigns the antepenult acute to this group. It does not call ἕκαστος a superlative.');
  group(['πολλοστός','εἰκοστός','τριακοστός','πεντηκοστός'], 'ultima',
    'More than two syllables; -στος, penultimate ο, used in expressions of quantity.',
    'All these qualifications belong to the passage’s rule: they are accented on the ultima.');
  group(['τορνευτός','στρατευτός','βουλευτός'], 'ultima',
    'Simple -τος words with more than two syllables and penultimate ευ.',
    'The qualification “simple” matters. The passage separately identifies ἀστράτευτος as a compound.');
  group(['ἀστράτευτος'], 'antepenult',
    'A compound contrasted with the simple ευ examples.',
    'The written example ἀστράτευτος has an antepenult acute; do not apply the simple-word rule to it.');
  group(['ἄλοιτος'], 'barytone',
    'Rare -τος words with more than two syllables and penultimate οι.',
    'The passage calls this group barytone and gives ἄλοιτος (“unjust and foul”). That label alone means non-final accent.');
  group(['τηλικοῦτος','τοιοῦτος','τοσοῦτος'], 'penult-circumflex',
    'The forms in -οῦτος.',
    'The passage explicitly gives a circumflex on the penult.');
  group(['ἄπαυστος','ἄθραυστος','ἄκλαυστος'], 'antepenult',
    'More than two syllables; -τος with penultimate αυ.',
    'The rule gives an antepenult acute, but ἐνιαυτός is explicitly recorded as an exception.');
  group(['ἐνιαυτός'], 'ultima',
    'The explicit exception to the penultimate αυ rule.',
    'The passage marks ἐνιαυτός as oxytone: acute on the ultima, despite its αυ.');
  const key = s => s.trim().replace(/^[··.,;:!?“”‘’"'()]+|[··.,;:!?“”‘’"'()]+$/gu, '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('el').replace(/ς/g, 'σ');
  const entries = new Map(rows.map(row => [key(row.word), row]));
  const input = document.querySelector('#word');
  const clue = document.querySelector('#clue');
  const feedback = document.querySelector('#feedback');
  const answers = [...document.querySelectorAll('[data-pattern]')];
  let selected = null;
  function showText(tag, text, className) {
    const node = document.createElement(tag);
    node.textContent = text;
    if (className) node.className = className;
    clue.appendChild(node);
    return node;
  }
  function explore() {
    selected = entries.get(key(input.value)) || null;
    clue.replaceChildren();
    answers.forEach(button => button.disabled = !selected);
    if (!key(input.value)) {
      showText('p', 'Enter a passage example or choose a button below the input.');
      feedback.textContent = 'Choose a word first.';
      return;
    }
    if (!selected) {
      showText('p', 'No match among these passage examples. No accent prediction is made.');
      feedback.textContent = 'Choose a listed word to try the exercise.';
      return;
    }
    showText('p', selected.rule, 'rule');
    showText('p', 'Pick the rule’s description to reveal the passage’s spelling.');
    feedback.textContent = 'Ready: select the rule’s description.';
  }
  document.querySelector('#lookup').addEventListener('click', explore);
  input.addEventListener('keydown', event => {if (event.key === 'Enter') explore();});
  input.addEventListener('input', () => {
    selected = null;
    answers.forEach(button => button.disabled = true);
    clue.textContent = 'Input changed. Explore this word to start a new question.';
    feedback.textContent = 'Explore the current input first.';
  });
  answers.forEach(button => button.addEventListener('click', () => {
    if (!selected) return;
    const correct = button.dataset.pattern === selected.pattern;
    clue.replaceChildren();
    const form = showText('p', selected.word, 'canonical');
    form.lang = 'grc';
    showText('p', selected.rule, 'rule');
    showText('p', selected.detail);
    feedback.textContent = (correct ? 'Correct. ' : 'Try again. ') + selected.word + ' — ' + labels[selected.pattern] + '.';
  }));
  rows.forEach(row => {
    const button = document.createElement('button');
    button.type = 'button';
    button.lang = 'grc';
    button.textContent = row.word;
    button.addEventListener('click', () => {input.value = row.word; explore();});
    document.querySelector('#examples').appendChild(button);
  });
  document.querySelector('#reset').addEventListener('click', () => {
    input.value = '';
    selected = null;
    clue.textContent = 'Choose a passage example to see its rule and qualification.';
    feedback.textContent = 'Choose a word first.';
    answers.forEach(button => button.disabled = true);
    input.focus();
  });
})();

