.btn.ghost{border-color:rgba(167,139,250,.35);background:rgba(167,139,250,.10)}
.btn.ghost:hover{background:rgba(167,139,250,.16)}

.out{margin-top:10px;padding:10px 12px;border-radius:12px;border:1px dashed rgba(185,189,216,.35);background:rgba(12,15,29,.55);min-height:92px}
