const $ = (sel, root=document) => root.querySelector(sel);
const chipsEl = $('#chips');
const outEl = $('#out');
const inpEl = $('#inp');
const derivOut = $('#derivOut');

const sampleChips = [
  'διπλοῦς','τριπλοῦς','τετραπλοῦς','πενταπλοῦς','ἁπλοῦς',
  'διπλόος','τριπλόος','πρωτόπλοος','ἁλίπλοος','εὔπλους','ὀλοός',
  'Σίστοος','Πείροος','Ἄθοος','Γένοος',
  'ἕβδομος','ὄγδοος','ἔννατος','δέκατος','εἰκοστός','τριακοστός',
  'σίκυος','Πέρυος','Φόγγυος','Αἴγυος','Τιτυός','εἰλυός'
];

function addChips(){
  chipsEl.innerHTML='';
  for(const w of sampleChips){
    const b=document.createElement('button');
    b.className='chip';
    b.type='button';
    b.textContent=w;
    b.addEventListener('click',()=>{inpEl.value=w; analyze(); inpEl.focus();});
    chipsEl.appendChild(b);
  }
}

// --- Greek-ish helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;
function stripCombining(s){return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');}
function stripPunct(s){return s.replace(/[··.,;:!?"'“”‘’()\[\]{}<>]/g,'').trim();}
function lowerGreek(s){return s.toLocaleLowerCase('el');}

function hasAccentMark(s){
  const n=s.normalize('NFD');
  return /[\u0300\u0301\u0342]/.test(n); // grave, acute, circumflex
}

function accentType(s){
  const n=s.normalize('NFD');
  if(n.includes('\u0342')) return 'circumflex';
  if(n.includes('\u0301')) return 'acute';
  if(n.includes('\u0300')) return 'grave';
  return 'none';
}

// Bounded reference forms: cited examples plus marked analogical contractions.
const catalog = new Map();
function wordKey(s){return lowerGreek(stripCombining(stripPunct(s))).replace(/ς/g,'σ');}
function addExamples(words, cat, shape, note){
  words.forEach(canonical => catalog.set(wordKey(canonical), {canonical, cat, shape, note, tag:'good'}));
}
addExamples(['διπλοῦς','τριπλοῦς'],
  'plous-simple-contracted', 'perispomenon: circumflex on the ultima',
  'Cited contracted simple derivatives. The passage explicitly contrasts διπλοῦς and τριπλοῦς with barytone compounds.');
addExamples(['τετραπλοῦς','πενταπλοῦς','ἁπλοῦς'],
  'plous-simple-contracted', 'perispomenon: circumflex on the ultima',
  'Analogical contractions of the cited τετραπλόος, πενταπλόος, ἁπλόος. These contracted spellings are displayed for comparison, not quoted as forms in the passage.');
addExamples(['διπλόος','τριπλόος','τετραπλόος','πενταπλόος','ἁπλόος'],
  'ploos-simple-uncontracted', 'oxytone: acute on the ultima',
  'The uncontracted simple derivatives have the written ultima acute in the passage; do not transfer the contracted circumflex to -πλόος.');
addExamples(['πρωτόπλοος','ἁλίπλοος'],
  'ploos-compound', 'proparoxytone: acute on the antepenult',
  'The passage explicitly assigns the antepenult acute to these compounds, because they are not simple.');
addExamples(['εὔπλους','εὔχρους','ἀλκίνους','εὔνους'],
  'compound-barytone', 'barytone: non-final accent',
  'These cited compounds are barytone. This term does not imply an antepenult acute; εὔπλους, for example, is accented on the penult.');
addExamples(['Σίστοος','Πείροος','Ἄθοος','Γένοος'],
  'proper-name-oos', 'proparoxytone: acute on the antepenult',
  'These are the cited proper names in -οος. An arbitrary word ending in -οος is not thereby a proper name.');
addExamples(['ἕβδομος','ὄγδοος','ἔννατος','δέκατος'],
  'ordinal-7-10', 'proparoxytone: acute on the antepenult',
  'These ordinal examples have the antepenult acute. The passage distinguishes the ordinals in -στος.');
addExamples(['εἰκοστός','τριακοστός'],
  'ordinal-stos', 'oxytone: acute on the ultima',
  'The passage gives these -στος ordinal examples as oxytone.');
addExamples(['ὀλοός'],
  'oloos', 'oxytone: acute on the ultima',
  'The passage explicitly says ὀλοός is oxytone, from ὀλῶ; it is not part of the proper-name rule.');
addExamples(['σίκυος','Πέρυος','Φόγγυος','Αἴγυος','Πατράσυος','Κάνδυος','Ἀλάσυος','Ἐρύγυος','Νώγυος','Μίνυος','Σίλλυος'],
  'short-upsilon-examples', 'proparoxytone: acute on the antepenult',
  'Cited examples of more than two syllables with short υ in the penult (Greek συνεσταλμένῳ). Letters alone do not establish quantity; this lookup matches only cited examples.');
addExamples(['Τιτυός','εἰλυός'],
  'upsilon-exceptions', 'oxytone: acute on the ultima',
  'The explicit exceptions Τιτυός and εἰλυός are oxytone; their υ does not have the short quantity specified in the preceding rule.');
function guessCategory(raw){
  return catalog.get(wordKey(raw)) || {cat:'unlisted', tag:'warn', canonical:'—', shape:'No prediction',
    note:'Not among this lookup’s reference examples. A suffix alone cannot establish the necessary name, derivation or quantity conditions.'};
}
function suggestAccentShape(cat){
  const item = [...catalog.values()].find(item => item.cat === cat);
  return item ? {shape:item.shape, why:'Accent pattern of the displayed reference form; not a validation of the accents typed.'} :
    {shape:'No prediction', why:'Choose a listed example. No general accent calculation is performed.'};
}

function analyze(){
  const raw = inpEl.value;
  const cleaned = stripPunct(raw);
  if(!cleaned){
    outEl.innerHTML = '<div class="muted">Type a Greek word above, then click Analyze.</div>';
    return;
  }

  const cat = guessCategory(cleaned);
  const acc = accentType(cleaned);
  const hasAcc = hasAccentMark(cleaned);
  const plain = stripCombining(cleaned);

  const sug = suggestAccentShape(cat.cat);

  outEl.innerHTML = `
    <div>
      <span class="tag ${cat.tag}">${cat.cat}</span>
      <span class="code">${escapeHtml(cleaned)}</span>
    </div>
    <div class="kv">
      <div class="k">Reference spelling</div><div class="v"><span class="code">${escapeHtml(cat.canonical)}</span></div>
      <div class="k">Letters without diacritics</div>
      <div class="v"><span class="code">${escapeHtml(plain)}</span></div>

      <div class="k">Accent marks found</div>
      <div class="v">${hasAcc ? `<b>${acc}</b>` : '<span class="muted">none detected</span>'}</div>

      <div class="k">Passage explanation</div>
      <div class="v">${escapeHtml(cat.note)}</div>

      <div class="k">Passage accent pattern</div>
      <div class="v">${escapeHtml(sug.shape)}<div class="muted">${escapeHtml(sug.why)}</div></div>
    </div>
  `;
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

// --- Derivation toy: base adverb -> -πλοος/-πλοῦς and feminine -πλῆ ---
function deriveFrom(base){
  const b = stripPunct(base);
  const bPlain = lowerGreek(stripCombining(b));

  const note = bPlain.endsWith('κις') ? 'Syncopation: removed -κις, as the passage describes.' :
    (bPlain === 'απαξ' ? 'The passage derives ἁπλόος from ἅπαξ.' : 'Simple derivative from the cited base adverb.');

  // map some known bases to conventional-looking outputs
  const map = {
    'δις': {m:'διπλοῦς', f:'διπλῆ', n:'διπλοῦν'},
    'τρις': {m:'τριπλοῦς', f:'τριπλῆ', n:'τριπλοῦν'},
    'τετρα': {m:'τετραπλοῦς', f:'τετραπλῆ', n:'τετραπλοῦν'},
    'πεντα': {m:'πενταπλοῦς', f:'πενταπλῆ', n:'πενταπλοῦν'},
    'εξα': {m:'ἑξαπλοῦς', f:'ἑξαπλῆ', n:'ἑξαπλοῦν'},
    'επτα': {m:'ἑπταπλοῦς', f:'ἑπταπλῆ', n:'ἑπταπλοῦν'},
    'απαξ': {m:'ἁπλοῦς', f:'ἁπλῆ', n:'ἁπλοῦν'}
  };

  let key = bPlain;
  if(key.endsWith('κις')) key = key.slice(0,-3);

  const forms = map[key];
  if(!forms) return {base:b, note:'No listed derivation.', m:'—', f:'—', n:'—'};

  return {base:b, note, ...forms};
}

let lastDerived = null;
function renderDerivation(){
  const base = $('#base').value;
  lastDerived = deriveFrom(base);
  derivOut.innerHTML = `
    <div><span class="tag good">derivation</span> from <span class="code">${escapeHtml(lastDerived.base)}</span></div>
    <div class="kv">
      <div class="k">Masc.</div><div class="v"><span class="code">${escapeHtml(lastDerived.m)}</span></div>
      <div class="k">Fem.</div><div class="v"><span class="code">${escapeHtml(lastDerived.f)}</span> <span class="muted">(cf. ἡ διπλῆ, τριπλῆ)</span></div>
      <div class="k">Neut.</div><div class="v"><span class="code">${escapeHtml(lastDerived.n)}</span></div>
      <div class="k">Note</div><div class="v">${escapeHtml(lastDerived.note || '—')}</div>
    </div>
  `;
}

$('#analyze').addEventListener('click', analyze);
$('#clear').addEventListener('click', ()=>{inpEl.value=''; outEl.innerHTML='<div class="muted">No analysis yet.</div>'; inpEl.focus();});
$('#derive').addEventListener('click', renderDerivation);
$('#base').addEventListener('change', renderDerivation);
$('#send').addEventListener('click', ()=>{
  renderDerivation();
  inpEl.value = lastDerived.m;
  analyze();
  inpEl.focus();
});

inpEl.addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(); });

addChips();
renderDerivation();

