:root{
  --bg:#0f1220;
  --card:#171a2b;
  --ink:#eef0ff;
  --muted:#b9bdd8;
  --faint:#8b90b3;
  --line:#2a2f4a;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#86efac;
  --warn:#fbbf24;
  --bad:#fb7185;
}
*{box-sizing:border-box}
body{margin:0;background:linear-gradient(180deg,#0b0e1a, #0f1220 30%, #0b0e1a);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,Roboto,Arial,"Noto Sans",sans-serif}
.wrap{max-width:1050px;margin:0 auto;padding:18px 16px 28px}
h2{margin:0 0 8px;font-size:20px;letter-spacing:.2px}
.sub{margin:0 0 14px;color:var(--muted)}
.grid{display:grid;grid-template-columns:1.1fr 1fr;gap:14px}
.card{background:rgba(23,26,43,.92);border:1px solid var(--line);border-radius:14px;padding:14px;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.card:nth-child(3){grid-column:1 / -1}
@media (max-width:900px){.grid{grid-template-columns:1fr}.card:nth-child(3){grid-column:auto}}

h3{margin:0 0 10px;font-size:16px}
.lbl{display:block;color:var(--muted);font-size:12px;margin:8px 0 6px}
.inp,.sel{width:100%;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:#0c0f1d;color:var(--ink);outline:none}
.inp:focus,.sel:focus{border-color:rgba(125,211,252,.7);box-shadow:0 0 0 3px rgba(125,211,252,.12)}
.row{display:flex;gap:10px;align-items:center;margin-top:10px;flex-wrap:wrap}
.btn{padding:9px 12px;border-radius:12px;border:1px solid rgba(125,211,252,.35);background:rgba(125,211,252,.12);color:var(--ink);cursor:pointer}
.btn:hover{background:rgba(125,211,252,.18)}
.btn:active{transform:translateY(1px)}
.btn.ghost{border-color:rgba(167,139,250,.35);background:rgba(167,139,250,.10)}
.btn.ghost:hover{background:rgba(167,139,250,.16)}

.out{margin-top:10px;padding:10px 12px;border-radius:12px;border:1px dashed rgba(185,189,216,.35);background:rgba(12,15,29,.55);min-height:92px}
.out.small{min-height:56px}
.muted{color:var(--faint)}

.help{margin-top:10px;border:1px solid rgba(185,189,216,.18);border-radius:12px;padding:8px 10px;background:rgba(12,15,29,.35)}
.help summary{cursor:pointer;color:var(--accent)}
.help ul{margin:8px 0 0 18px;color:var(--muted)}

.mini{margin-top:12px}
.miniTitle{font-size:12px;color:var(--muted);margin-bottom:6px}
.chips{display:flex;flex-wrap:wrap;gap:8px}
.chip{user-select:none;cursor:pointer;padding:6px 10px;border-radius:999px;border:1px solid rgba(185,189,216,.22);background:rgba(12,15,29,.35);color:var(--ink);font-size:13px}
.chip:hover{border-color:rgba(125,211,252,.5)}

.tag{display:inline-block;padding:2px 8px;border-radius:999px;font-size:12px;margin-right:6px;border:1px solid transparent}
.tag.good{background:rgba(134,239,172,.12);border-color:rgba(134,239,172,.35);color:var(--good)}
.tag.warn{background:rgba(251,191,36,.10);border-color:rgba(251,191,36,.35);color:var(--warn)}
.tag.bad{background:rgba(251,113,133,.10);border-color:rgba(251,113,133,.35);color:var(--bad)}

.kv{display:grid;grid-template-columns:140px 1fr;gap:6px 10px;margin-top:8px}
.k{color:var(--muted);font-size:12px}
.v{color:var(--ink)}
.code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;background:rgba(12,15,29,.55);border:1px solid rgba(185,189,216,.18);padding:1px 6px;border-radius:8px}
.note{margin:10px 0 0;color:var(--faint);font-size:12px}
.sub2{margin:0 0 10px;color:var(--muted)}
.foot{margin-top:14px;color:var(--faint);font-size:12px;border-top:1px solid rgba(185,189,216,.14);padding-top:10px}

original.gadget_js:
const $ = (sel, root=document) => root.querySelector(sel);
const chipsEl = $('#chips');
const outEl = $('#out');
const inpEl = $('#inp');
const derivOut = $('#derivOut');

const sampleChips = [
  'διπλοῦς','τριπλοῦς','τετραπλοῦς','πενταπλοῦς','ἁπλοῦς',
  'πρωτόπλοος','ἁλίπλοος',
  'Σίστοος','Πείροος','Ἄθοος','Γένοος',
  'ἕβδομος','ὄγδοος','ἔννατος','δέκατος','εἰκοστός','τριακοστός',
  'σίκυος','Πέρυος','Φόγγυος','Αἴγυος','Τιτυός','εἰλυός'
];

function addChips(){
  chipsEl.innerHTML='';
  for(const w of sampleChips){
    const b=document.createElement('button');
    b.className='chip';
    b.type='button';
    b.textContent=w;
    b.addEventListener('click',()=>{inpEl.value=w; analyze(); inpEl.focus();});
    chipsEl.appendChild(b);
  }
}

// --- Greek-ish helpers (toy-level) ---
const COMBINING = /[\u0300-\u036f]/g;
function stripCombining(s){return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');}
function stripPunct(s){return s.replace(/[··.,;:!?"'“”‘’()\[\]{}<>]/g,'').trim();}
function lowerGreek(s){return s.toLocaleLowerCase('el');}

function hasAccentMark(s){
  const n=s.normalize('NFD');
  return /[\u0300\u0301\u0342]/.test(n); // grave, acute, circumflex
}

function accentType(s){
  const n=s.normalize('NFD');
  if(n.includes('\u0342')) return 'circumflex';
  if(n.includes('\u0301')) return 'acute';
  if(n.includes('\u0300')) return 'grave';
  return 'none';
}

function endsWithAny(s, arr){return arr.some(x=>s.endsWith(x));}

function guessCategory(raw){
  const w = lowerGreek(stripPunct(raw));
  const plain = lowerGreek(stripPunct(stripCombining(raw)));

  // ordinals
  if(endsWithAny(plain, ['κοστος','κοστός','κοστοσ'])){
    return {cat:'ordinal-20+', tag:'warn', note:'Looks like an ordinal in -κοστός (Herodian: often oxytone).'};
  }
  if(endsWithAny(plain, ['βδομος','βδομοσ','γδοος','γδοοσ','ννατος','ννατοσ','κατος','κατοσ'])){
    return {cat:'ordinal-7-10', tag:'good', note:'Looks like an ordinal (ἕβδομος/ὄγδοος/ἔννατος/δέκατος) → often proparoxytone.'};
  }

  // -oos proper names
  if(endsWithAny(plain, ['οος','οοσ'])){
    return {cat:'-oos', tag:'good', note:'Ends in -οος (Herodian: proper names in -οος often proparoxytone).'};
  }

  // -plous / -ploos
  if(plain.includes('πλο') && (endsWithAny(plain,['πλους','πλοῦς','πλοος','πλοοσ']))){
    // compounds: very rough—look for obvious first members
    if(plain.startsWith('πρωτο') || plain.startsWith('αλι') || plain.startsWith('ευ') || plain.includes('τοπλο')){
      return {cat:'plous-compound', tag:'warn', note:'Looks like a compound with -πλοος/-πλοῦς (Herodian: e.g. πρωτόπλοος, ἁλίπλοος → proparoxytone).'};
    }
    return {cat:'plous-simple', tag:'good', note:'Looks like a simple derivative in -πλοος/-πλοῦς (Herodian: διπλοῦς, τριπλοῦς etc. are treated as simple derivatives).'};
  }

  // -yos
  if(endsWithAny(plain,['υος','υοσ','υός','υός'])){
    // exceptions mentioned
    if(plain.includes('τιτυ') || plain.includes('ειλυ')){
      return {cat:'-yos-exc', tag:'warn', note:'Matches Herodian’s exceptions (Τιτυός, εἰλυός) → oxytone; υ not “contracted”.'};
    }
    return {cat:'-yos', tag:'good', note:'Ends in -υος (Herodian: some hyperdisyllables with “contracted” υ in penult → proparoxytone).'};
  }

  return {cat:'other', tag:'bad', note:'No specific pattern recognized from this passage. Still shows accent marks found.'};
}

function suggestAccentShape(cat){
  // We do NOT compute real accent placement; we just suggest a label.
  switch(cat){
    case 'plous-simple':
      return {shape:'perispomenon (circumflex) on the ending (toy)', why:'Herodian contrasts διπλοῦς/τριπλοῦς (circumflex) with barytone compounds.'};
    case 'plous-compound':
      return {shape:'proparoxytone (toy)', why:'Herodian: πρωτόπλοος, ἁλίπλοος are proparoxytone because not simple.'};
    case '-oos':
      return {shape:'proparoxytone (toy)', why:'Herodian: proper names in -οος are proparoxytone (Σίστοος, Πείροος, Ἄθοος).'};
    case 'ordinal-7-10':
      return {shape:'proparoxytone (toy)', why:'Herodian: ἕβδομος, ὄγδοος, ἔννατος, δέκατος are proparoxytone.'};
    case 'ordinal-20+':
      return {shape:'oxytone (toy)', why:'Herodian: εἰκοστός, τριακοστός etc. are oxytone.'};
    case '-yos':
      return {shape:'proparoxytone (toy)', why:'Herodian: many -υος hyperdisyllables with “contracted” υ in penult are proparoxytone.'};
    case '-yos-exc':
      return {shape:'oxytone (toy)', why:'Herodian: Τιτυός and εἰλυός are oxytone; υ not contracted.'};
    default:
      return {shape:'(no suggestion)', why:'Not covered by this toy.'};
  }
}

function analyze(){
  const raw = inpEl.value;
  const cleaned = stripPunct(raw);
  if(!cleaned){
    outEl.innerHTML = '<div class="muted">Type a Greek word above, then click Analyze.</div>';
    return;
  }

  const cat = guessCategory(cleaned);
  const acc = accentType(cleaned);
  const hasAcc = hasAccentMark(cleaned);
  const plain = stripCombining(cleaned);

  const sug = suggestAccentShape(cat.cat);

  outEl.innerHTML = `
    <div>
      <span class="tag ${cat.tag}">${cat.cat}</span>
      <span class="code">${escapeHtml(cleaned)}</span>
    </div>
    <div class="kv">
      <div class="k">Unaccented (toy)</div>
      <div class="v"><span class="code">${escapeHtml(plain)}</span></div>

      <div class="k">Accent marks found</div>
      <div class="v">${hasAcc ? `<b>${acc}</b>` : '<span class="muted">none detected</span>'}</div>

      <div class="k">Herodian-ish hint</div>
      <div class="v">${escapeHtml(cat.note)}</div>

      <div class="k">Suggested accent shape</div>
      <div class="v">${escapeHtml(sug.shape)}<div class="muted">${escapeHtml(sug.why)}</div></div>
    </div>
  `;
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

// --- Derivation toy: base adverb -> -πλοος/-πλοῦς and feminine -πλῆ ---
function deriveFrom(base){
  const b = stripPunct(base);
  const bPlain = lowerGreek(stripCombining(b));

  // syncopate -κις if present
  let stem = b;
  let note = '';
  if(bPlain.endsWith('κις')){
    stem = b.slice(0, -2); // remove final ς? careful: 'κις' length 3; but polytonic may vary
    // safer: remove last 3 chars in NFC
    stem = b.substring(0, b.length-3);
    note = "Syncopation: removed -κις (as Herodian says).";
  } else if(bPlain.endsWith('παξ')){
    // ἅπαξ -> ἁπλο-
    note = "Special: ἅπαξ → ἁπλο- (toy).";
  }

  // map some known bases to conventional-looking outputs
  const map = {
    'δις': {m:'διπλοῦς', f:'διπλῆ', n:'διπλοῦν'},
    'τρις': {m:'τριπλοῦς', f:'τριπλῆ', n:'τριπλοῦν'},
    'τετρα': {m:'τετραπλοῦς', f:'τετραπλῆ', n:'τετραπλοῦν'},
    'πεντα': {m:'πενταπλοῦς', f:'πενταπλῆ', n:'πενταπλοῦν'},
    'εξα': {m:'ἑξαπλοῦς', f:'ἑξαπλῆ', n:'ἑξαπλοῦν'},
    'επτα': {m:'ἑπταπλοῦς', f:'ἑπταπλῆ', n:'ἑπταπλοῦν'},
    'απαξ': {m:'ἁπλοῦς', f:'ἁπλῆ', n:'ἁπλοῦν'}
  };

  let key = bPlain;
  if(key.endsWith('κις')) key = key.slice(0,-3);

  // normalize rough breathing variants for toy
  key = key
    .replaceAll('ἑ','ε')
    .replaceAll('ἕ','ε')
    .replaceAll('ἑξ','εξ')
    .replaceAll('ἑπ','επ')
    .replaceAll('ἅ','α')
    .replaceAll('ἁ','α');

  let forms = map[key];
  if(!forms){
    // fallback: just glue
    const glued = stripPunct(stem) + 'πλοῦς';
    forms = {m:glued, f:stripPunct(stem)+'πλῆ', n:stripPunct(stem)+'πλοῦν'};
    note = note || 'Fallback: glued stem + πλοῦς (toy).';
  }

  return {base:b, note, ...forms};
}

let lastDerived = null;
function renderDerivation(){
  const base = $('#base').value;
  lastDerived = deriveFrom(base);
  derivOut.innerHTML = `
    <div><span class="tag good">derivation</span> from <span class="code">${escapeHtml(lastDerived.base)}</span></div>
    <div class="kv">
      <div class="k">Masc.</div><div class="v"><span class="code">${escapeHtml(lastDerived.m)}</span></div>
      <div class="k">Fem.</div><div class="v"><span class="code">${escapeHtml(lastDerived.f)}</span> <span class="muted">(cf. ἡ διπλῆ, τριπλῆ)</span></div>
      <div class="k">Neut.</div><div class="v"><span class="code">${escapeHtml(lastDerived.n)}</span></div>
      <div class="k">Note</div><div class="v">${escapeHtml(lastDerived.note || '—')}</div>
    </div>
  `;
}

$('#analyze').addEventListener('click', analyze);
$('#clear').addEventListener('click', ()=>{inpEl.value=''; outEl.innerHTML='<div class="muted">No analysis yet.</div>'; inpEl.focus();});
$('#derive').addEventListener('click', renderDerivation);
$('#send').addEventListener('click', ()=>{
  if(!lastDerived) renderDerivation();
  inpEl.value = lastDerived.m;
  analyze();
  inpEl.focus();
});

inpEl.addEventListener('keydown', (e)=>{ if(e.key==='Enter') analyze(); });

addChips();
renderDerivation();
